import json, sys
data = json.load\(sys.stdin\)

# 1. Search for read:issue-details:jira anywhere in the spec
spec_str = json.dumps\(data\)
if 'read:issue-details:jira' in spec_str:
    print\('read:issue-details:jira FOUND in spec'\)
    # Find which endpoints use it
    for path, path_item in data.get\('paths', {}\).items\(\):
        for method, op in path_item.items\(\):
            if not isinstance\(op, dict\):
                continue
            for scope_block in op.get\('x-atlassian-oauth2-scopes', []\):
                if 'read:issue-details:jira' in scope_block.get\('scopes', []\):
                    print\(f'  -> {method.upper\(\)} {path} \(state: {scope_block[\\"state\\"]}\)'\)
else:
    print\('read:issue-details:jira NOT FOUND anywhere in spec'\)

print\(\)

# 2. Search for _edge/tenant_info
if '_edge/tenant_info' in spec_str or 'tenant_info' in spec_str:
    print\('tenant_info endpoint FOUND in spec'\)
    for path in data.get\('paths', {}\):
        if 'tenant' in path.lower\(\):
            print\(f'  path: {path}'\)
else:
    print\('_edge/tenant_info NOT FOUND in spec \(unauthenticated endpoint, not in Jira REST spec\)'\)

print\(\)

# 3. Show all scopes used in GET /rest/api/3/issue/{issueIdOrKey} Beta block
issue_path = data['paths'].get\('/rest/api/3/issue/{issueIdOrKey}', {}\)
get_op = issue_path.get\('get', {}\)
print\('=== GET issue - all x-atlassian-oauth2-scopes blocks ==='\)
for block in get_op.get\('x-atlassian-oauth2-scopes', []\):
    print\(f'  state={block[\\"state\\"]}: {block[\\"scopes\\"]}'\)

print\(\)
put_op = issue_path.get\('put', {}\)
print\('=== PUT issue - all x-atlassian-oauth2-scopes blocks ==='\)
for block in put_op.get\('x-atlassian-oauth2-scopes', []\):
    print\(f'  state={block[\\"state\\"]}: {block[\\"scopes\\"]}'\)
